import shutil
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent


def main() -> int:
    uv = shutil.which("uv")
    if uv is None:
        print("uv not found on PATH; run `factory doctor` for install hints", file=sys.stderr)
        return 2
    argv = [uv, "export", "--frozen", "--no-dev", "--format", "requirements.txt", "-o", str(ROOT / "requirements.lock.txt")]
    return subprocess.run(argv, cwd=ROOT, check=False).returncode


if __name__ == "__main__":
    sys.exit(main())
